def gitblob(p):return subprocess.check_output(['git','-C',str(REPO),'hash-object',str(p.relative_to(REPO))],text=True).strip()
def source(n,sid,title,url,date,loc,passage,agency,rights='authoritative source'):
 return {'source_id':f'Q{n}-S{sid}','agency':agency,'title':title,'url':url,'publication_or_revision_date':date,'retrieved_at':'2026-09-06','section_locator':loc,'supporting_passage':passage,'rights_status':rights,'official_exam_specification':url.startswith('https://www.usmle.org/')}
def usmle_source(n,bp):
 return source(n,1,'Step 1 Exam Content',USMLE_URL,'current official specifications',f"Step 1 Content Specifications — {bp['primary_system']}; Step 1 Physician Tasks/Competencies Specifications — {bp['primary_competency']}; Step 1 Discipline Specifications — {', '.join(bp['disciplines'])}",f"Supports classification under {bp['primary_system']}, {bp['primary_competency']}, and the listed Step 1 disciplines.",'USMLE','official exam specification')
def S(n,sid,title,pmid,year,passage):return source(n,sid,title,f'https://pubmed.ncbi.nlm.nih.gov/{pmid}/',year,'Abstract',passage,'National Library of Medicine / PubMed','authoritative indexed source')
def O(n,sid,agency,title,url,date,loc,passage):return source(n,sid,title,url,date,loc,passage,agency,'official U.S. government source')
def make(*,n,system,comp,path,disc,coverage,vignette,lead,options,key,tested,keyexp,obj,anchor,refs,fingerprint,wrong,steps=4):
 bp={'primary_system':system,'official_outline_path':[system],'internal_content_path':path,'primary_competency':comp,'disciplines':disc,'coverage_deficit_addressed':coverage}
 de={}
 for L,opt in options.items():
  if L==key: de[L]='Correct. '+keyexp
  else: de[L]=f"Option {L} proposes '{opt}'. It is not selected because it does not account for {anchor}; {wrong[L]}"
 sources=[usmle_source(n,bp)]+refs; srcids=[s['source_id'] for s in refs]
 ev=[{'claim_id':f'Q{n}-{L}','option':L,'claim':de[L],'source_ids':srcids,'direct_or_inference':'direct' if L==key else 'inference','item_specific_application':'The complete vignette and source-supported discriminator resolve this option under the single-best-answer lead-in.'} for L in 'ABCDE']
 return {'num':n,'country_scope':'United States','specification_version':'USMLE Step 1 current official specifications verified 2026-09-06','blueprint':bp,'item':{'vignette':vignette,'lead_in':lead,'options':options,'intended_key':key,'difficulty':'moderate-hard','tested_construct':tested,'reasoning_steps_count':steps},'explanation':{'key_explanation':keyexp,'distractor_explanations':de,'educational_objective':obj},'evidence_map':ev,'sources':sources,'semantic_fingerprint':fingerprint,'author_self_audit':{k:10 for k in ['blueprint_fidelity','key_correctness','distractor_integrity','single_best_answer','reasoning_and_difficulty','item_writing','cueing_bias_fairness','evidence_quality','originality_duplication_rights','technical_integrity']}|{'unresolved_concerns':[],'suggested_changes':[]},'status':'CANDIDATE_FROZEN'}

